import{z as i,x as A,o as t,c as p,q as E,j as d,D as n,d as r,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"流控与窗口","description":"","frontmatter":{"title":"流控与窗口","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-window.md","filePath":"cs/tcp-window.md","lastUpdated":1791413859000}'),B={name:"cs/tcp-window.md"};function c(u,a,m,D,w,C){const o=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=E('<h1 id="流控与窗口" tabindex="-1">流控与窗口 <a class="header-anchor" href="#流控与窗口" aria-label="Permalink to &quot;流控与窗口&quot;">​</a></h1><div class="epigraph"><p>接收窗口通告还能再收多少字节；发送方不得让未确认数据超出窗口，以免淹没对端。</p><footer>—— 据 RFC 793 窗口字段；Kurose and Ross 对滑动窗口的整理</footer></div><p><a href="/cs/tcp-sack">上一课</a>保证最终送达，若发送方无视接收缓冲，重传队列会在接收端溢出，只能丢——再重传，活锁。缺口是<strong>流控</strong>：滑动窗口，通告 <code>rwnd</code>。本课不把拥塞窗口 <code>cwnd</code> 当作同一旋钮。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>套接字接收缓冲有限，进程可能不及时 <code>read</code>（调度在跑别人）。TCP 头窗口字段告诉对端：可发送的序号上限 = ACK + rwnd。发送方维护已发送未确认的飞行字节 ≤ rwnd。缺口不是 ISN，而是这条信用。零窗口时对端停发，稍后窗口更新；为防更新丢失，有持续定时器探一字节。</p><p>本课不把糊涂窗口综合症的全部修复代码写完，只承认小窗口应避免。</p><p><span class="marginnote">滑动窗口把流水线引入重传课的停等：带宽时延积大时，窗口必须够大，否则链路空转。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接收：应用取走数据则 rwnd 增大，发窗口更新。发送：新数据与重传都受 rwnd 限制。与<a href="/cs/monitor-condvar">管程</a>类比：缓冲满则发送方在内核睡，像管道写端；唤醒来自收到更大窗口或 ACK。</p>',9)),(t(),d(l,null,{default:n(()=>[s(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUF%5B%22%E6%8E%A5%E6%94%B6%E7%BC%93%E5%86%B2%E5%89%A9%E4%BD%99%22%5D%20--%3E%20RWND%5B%22%E9%80%9A%E5%91%8A%20rwnd%22%5D%0A%20%20RWND%20--%3E%20SEND%5B%22%E9%A3%9E%E8%A1%8C%E5%AD%97%E8%8A%82%20%E2%89%A4%20rwnd%22%5D%0A%20%20SEND%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%20read%20%E9%87%8A%E6%94%BE%E7%BC%93%E5%86%B2%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},'数字实例：对端回 ack=5000、rwnd=8000，意思是"5000 之前都确认了，你最多还能发到第 13000 字节"；飞行字节一到 13000 就必须停，等下一份窗口通告。')],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[r("流控保护"),e("strong",null,"端"),r("，不保护中间路由器队列——那是拥塞控制。两者都限制飞行字节，但信号来源不同：rwnd 来自对端主机，丢包来自网络。实现取 "),e("code",null,"min(rwnd, cwnd)"),r("，cwnd 后课才出现。端到端：流控是两端协商，符合 Saltzer；交换机的 PAUSE 是链路层另一回事。")],-1)),a[6]||(a[6]=e("p",null,"窗口卡在零时双方怎么办？发送方不能干等，持续定时器给出一条恢复路径：",-1)),(t(),d(l,null,{default:n(()=>[s(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E6%94%B6%E5%88%B0%20rwnd%20%3D%200%22%5D%20--%3E%20STOP%5B%22%E5%81%9C%E5%8F%91%E6%96%B0%E6%95%B0%E6%8D%AE%2C%20%E5%90%AF%E5%8A%A8%E6%8C%81%E7%BB%AD%E5%AE%9A%E6%97%B6%E5%99%A8%22%5D%0A%20%20STOP%20--%3E%20P%5B%22%E5%AE%9A%E6%97%B6%E5%99%A8%E5%88%B0%E6%9C%9F%2C%20%E5%8F%91%201%20%E5%AD%97%E8%8A%82%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20P%20--%3E%20Q%7B%22%E5%AF%B9%E7%AB%AF%20ACK%20%E4%BB%8D%E6%8A%A5%200%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20P2%5B%22%E6%8B%89%E9%95%BF%E9%97%B4%E9%9A%94%E7%BB%A7%E7%BB%AD%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20P2%20--%3E%20P%0A%20%20Q%20--%3E%7C%22%E5%90%A6%2C%20%E7%AA%97%E5%8F%A3%E9%87%8D%E6%96%B0%E6%89%93%E5%BC%80%22%7C%20RES%5B%22%E6%81%A2%E5%A4%8D%E5%8F%91%E9%80%81%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">术语翻译：持续定时器是&quot;窗口卡在零时发送方的闹钟&quot;——定期发一个字节去问&quot;现在能收了吗&quot;，防止对端的窗口更新报文丢了、双方互相干等到底。</span></p><p>与 DMA：网卡可以比应用快，窗口把不匹配关在传输层，而不是让内核无限占页。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入接收卸载的硬件窗口。不把 BDP 测量实验写进主干。窗口缩放选项（RFC 7323）承认 16 位字段不够，点名即可。网络自己的队列溢出，后课 AIMD。</p><p>发送方还受 MSS 与 Nagle 影响：小写可被合并。Nagle 与延迟 ACK 互相等待是经典坑，本课点名不调参。</p><p>窗口通告以字节计，不是以段计；MSS 只限制单段大小。</p><p>后课默认：发送受接收窗口约束。网络拥塞时即使 rwnd 很大也要减速，后课拥塞控制。</p><p><span class="marginnote">常见误区：容易把 rwnd 和 cwnd 当同一个旋钮。rwnd 防的是&quot;淹了对端缓冲&quot;，cwnd 防的是&quot;挤爆中间网络&quot;；实际生效的是两者中较小的那个，哪个小哪个先卡住发送。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rwnd 是接收方信用；滑动窗口流水线化可靠传输。</li><li>保护端缓冲，不保护路由器。</li><li>拥塞窗口是另一条上限，后课。</li><li>出处：RFC 793；Kurose and Ross；Tanenbaum <em>Computer Networks</em>。</li></ul>',10))])}const P=i(B,[["render",c]]);export{f as __pageData,P as default};
